package main

import (
	"bufio"
	"flag"
	"fmt"
	"net/http"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// Matches lines like: 0x8141\t0xAC00\t# ...
var lineRe = regexp.MustCompile(`^0x([0-9A-Fa-f]{4})\s+0x([0-9A-Fa-f]{4,6})`)

type dbcsIndex struct {
	Offset uint32
	Low    byte
	High   byte
}

func main() {
	inURL := flag.String("url", "", "URL to Unicode JOHAB.TXT")
	outPath := flag.String("output", "", "Output .go file (default: stdout)")
	pkg := flag.String("package", "korean", "Go package name")
	flag.Parse()

	if *inURL == "" {
		fmt.Fprintln(os.Stderr, "usage: johab-mapgen -url <https://.../JOHAB.TXT> [-output korean/tables_generated.go]")
		os.Exit(2)
	}

	resp, err := http.Get(*inURL)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		panic(fmt.Sprintf("GET %s: %s", *inURL, resp.Status))
	}

	// Decode map: Johab code (0x0000..0xFFFF) -> Unicode scalar (uint32).
	// Encode map: Unicode BMP (uint32) -> Johab code. Last mapping wins to match
	// the previous loader behavior.
	dec := make(map[uint16]uint32)
	enc := make(map[uint32]uint16)

	scanner := bufio.NewScanner(resp.Body)
	// Be defensive in case the source ever contains long lines.
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		m := lineRe.FindStringSubmatch(line)
		if m == nil {
			continue
		}

		code64, err := strconv.ParseUint(m[1], 16, 16)
		if err != nil {
			panic(err)
		}
		rune64, err := strconv.ParseUint(m[2], 16, 32)
		if err != nil {
			panic(err)
		}

		code := uint16(code64)
		r := uint32(rune64)

		// The mapping file is for double-byte sequences; ignore single-byte codes if any.
		if code <= 0x00FF {
			continue
		}

		if prev, ok := dec[code]; ok && prev != r {
			panic(fmt.Sprintf("duplicate code 0x%04X: was U+%04X now U+%04X", code, prev, r))
		}
		dec[code] = r
		if r <= 0xFFFF {
			enc[r] = code
		}
	}
	if err := scanner.Err(); err != nil {
		panic(err)
	}

	// Build CPython-style decode tables:
	//   - 256-entry index by lead byte
	//   - contiguous decode map slices per lead byte covering [low..high]
	var decIndex [256]dbcsIndex
	var decMap []uint32

	for b1 := 0; b1 < 256; b1++ {
		lows := make([]int, 0, 64)
		for code := range dec {
			if int(code>>8) == b1 {
				lows = append(lows, int(code&0xFF))
			}
		}
		if len(lows) == 0 {
			continue
		}
		sort.Ints(lows)
		low := byte(lows[0])
		high := byte(lows[len(lows)-1])

		offset := uint32(len(decMap))
		blockLen := int(high) - int(low) + 1
		block := make([]uint32, blockLen)
		for lo := int(low); lo <= int(high); lo++ {
			code := uint16(b1)<<8 | uint16(byte(lo))
			block[lo-int(low)] = dec[code]
		}
		decMap = append(decMap, block...)
		decIndex[b1] = dbcsIndex{Offset: offset, Low: low, High: high}
	}

	// Build CPython-style encode tables:
	//   - 256-entry index by Unicode high byte
	//   - contiguous encode map slices per high byte covering [low..high]
	var encIndex [256]dbcsIndex
	var encMap []uint16
	for hb := 0; hb < 256; hb++ {
		lows := make([]int, 0, 64)
		for r := range enc {
			if int((r>>8)&0xFF) == hb {
				lows = append(lows, int(r&0xFF))
			}
		}
		if len(lows) == 0 {
			continue
		}
		sort.Ints(lows)
		low := byte(lows[0])
		high := byte(lows[len(lows)-1])
		offset := uint32(len(encMap))
		blockLen := int(high) - int(low) + 1
		block := make([]uint16, blockLen)
		for lo := int(low); lo <= int(high); lo++ {
			r := uint32(hb)<<8 | uint32(byte(lo))
			block[lo-int(low)] = enc[r]
		}
		encMap = append(encMap, block...)
		encIndex[hb] = dbcsIndex{Offset: offset, Low: low, High: high}
	}

	out := os.Stdout
	if *outPath != "" {
		of, err := os.Create(*outPath)
		if err != nil {
			panic(err)
		}
		defer of.Close()
		out = of
	}

	w := bufio.NewWriter(out)
	defer w.Flush()

	fmt.Fprintln(w, "// Code generated by cmd/johab-mapgen; DO NOT EDIT.")
	fmt.Fprintln(w, "")
	fmt.Fprintf(w, "package %s\n\n", *pkg)

	fmt.Fprintln(w, "// dbcsIndex mirrors CPython's dbcs_index/unim_index style tables.")
	fmt.Fprintln(w, "// Offset is into a contiguous map; Low/High bound the second byte (or low Unicode byte).")
	fmt.Fprintln(w, "type johabIndex struct { Offset uint32; Low, High byte }")
	fmt.Fprintln(w, "")

	fmt.Fprintf(w, "var johabDecmap = [...]uint32{\n")
	for i, v := range decMap {
		if i%12 == 0 {
			fmt.Fprint(w, "\t")
		}
		fmt.Fprintf(w, "0x%X, ", v)
		if i%12 == 11 {
			fmt.Fprintln(w)
		}
	}
	if len(decMap)%12 != 0 {
		fmt.Fprintln(w)
	}
	fmt.Fprintln(w, "}")
	fmt.Fprintln(w, "")

	fmt.Fprintln(w, "var johabDecIndex = [...]johabIndex{")
	for i := 0; i < 256; i++ {
		idx := decIndex[i]
		fmt.Fprintf(w, "\t{Offset:%d, Low:0x%02X, High:0x%02X},\n", idx.Offset, idx.Low, idx.High)
	}
	fmt.Fprintln(w, "}")
	fmt.Fprintln(w, "")

	fmt.Fprintln(w, "var johabEncmap = [...]uint16{")
	for i, v := range encMap {
		if i%16 == 0 {
			fmt.Fprint(w, "\t")
		}
		fmt.Fprintf(w, "0x%04X, ", v)
		if i%16 == 15 {
			fmt.Fprintln(w)
		}
	}
	if len(encMap)%16 != 0 {
		fmt.Fprintln(w)
	}
	fmt.Fprintln(w, "}")
	fmt.Fprintln(w, "")

	fmt.Fprintln(w, "var johabEncIndex = [...]johabIndex{")
	for i := 0; i < 256; i++ {
		idx := encIndex[i]
		fmt.Fprintf(w, "\t{Offset:%d, Low:0x%02X, High:0x%02X},\n", idx.Offset, idx.Low, idx.High)
	}
	fmt.Fprintln(w, "}")
}
